// TaiSEIA device-side framing. Protocol evidence and simulator policy are kept separate.
export const COMMON={0:'註冊／設備識別',1:'Class ID',2:'協定版本',3:'保留命令',4:'SA Type ID',5:'品牌',6:'型號',7:'支援服務',8:'完整狀態'};
export const xor=bytes=>Array.from(bytes).reduce((a,b)=>a^b,0);
